/// <summary>
/// Agent C - Skill-Description-Optimizer. Turns evidence that a skill was chosen wrongly into a pending
/// ProposedSkillChange with a tighter description, generated by the cheapest enabled model. NEVER mutates
/// the live skill - the gate does that, and only if the change measures clean.
/// Two sources feed it, and each is spent exactly once.
/// (1) Recent trajectories where a user flagged the chosen skill as wrong. Their intended target is
/// frozen as a golden case first, and the trajectories are stamped with a consumption watermark.
/// (2) The pure selection misses of the latest full eval run: items where the expected tool WAS in the
/// toolset and the model picked another. Only items of the TRAIN partition qualify - a proposal built
/// from a holdout item would be judged by the very item it came from - and each consumed item is
/// watermarked on eval_run_items. Retrieval misses are deliberately not a source: no wording of a
/// description can fix a tool that was never offered.
/// The train ids are computed from the goldset first and handed to the store as part of the query, so
/// the row limit can only ever be filled with rows this source may actually spend. Filtering the
/// partition after the limit made the tail unreachable: a window of holdout ids, or of groups the
/// open-proposal check skips, stayed the window on every following run.
/// A group skipped because its skill already carries an open proposal is deliberately NOT watermarked.
/// Nothing was spent on it, so it returns on the next run - and is spendable again as soon as a person
/// has decided the proposal that blocks it.
/// The goldset branch is capped at MaxGoldsetProposalsPerRun, largest evidence first. Every group is a
/// paid model call plus a pending row, and the branch sees hundreds of items where the corrections see
/// the handful of turns a person flagged.
/// Goldset-born proposals carry Origin = goldset_eval, because the sharpener gates them with an
/// additional targeted holdout replay. They freeze no golden case: the seeder already wrote one for
/// every goldset item that names an expected tool. The pending window the sharpener reads is ordered
/// correction-born first, so these bulk-written rows never displace a correction.
/// </summary>
/// <param name="trajectoryRepository">Recent unconsumed corrected trajectories</param>
/// <param name="proposalRepository">Where proposals are written, and the open-proposal check</param>
/// <param name="agentSkillRepository">Resolves the wrongly chosen skill and its current description</param>
/// <param name="agentRepository">Supplies the default agent</param>
/// <param name="caseRepository">Resolves the skill a correction named as the intended target</param>
/// <param name="goldenCaseRepository">Where a correction's intended target is frozen</param>
/// <param name="evalRunRepository">Finds the latest full eval run the misses are read from</param>
/// <param name="evalRunItemRepository">The unconsumed selection misses of the train items and their watermark</param>
/// <param name="goldsetLoader">Supplies the user message behind a goldset item id</param>
/// <param name="providerFactory">Factory to obtain an LLM provider</param>
/// <param name="llmRepository">Used to find the cheapest enabled model</param>
/// <param name="logger">Logger</param>

using System.Text.Json;
using Klacks.Api.Application.Services.Assistant.Evaluation.TurnEval;
using Klacks.Api.Domain.Constants;
using Klacks.Api.Domain.Interfaces.Assistant;
using Klacks.Api.Domain.Models.Assistant;
using Klacks.Api.Domain.Services.Assistant;
using Klacks.Api.Domain.Services.Assistant.Providers;

namespace Klacks.Api.Application.Services.Assistant.Evaluation;

public class SkillDescriptionOptimizer : ISkillDescriptionOptimizer
{
    private const int OptimizerMaxTokens = 256;
    private const int MaxEvidencePerProposal = 5;
    private const double OptimizerTemperature = 0.2;
    private const int MinDescriptionLength = 10;
    private const int MaxDescriptionLength = 500;

    private static readonly string SystemPrompt =
        "You tighten skill descriptions for an assistant that uses semantic search over descriptions to pick the right skill. " +
        "Given a user query that the assistant misclassified into the WRONG skill, rewrite the description of that wrong skill " +
        "so it would NOT match queries of that shape next time, while still describing what the skill actually does. " +
        "Constraints: keep it under 400 characters, English, factual, no marketing fluff, no examples in the description, " +
        "do not invent capabilities the skill does not have. " +
        "Respond ONLY with a JSON object: {\"description\":\"...\",\"justification\":\"...\"}.";

    private readonly ISkillSelectionTrajectoryRepository _trajectoryRepository;
    private readonly IProposedSkillChangeRepository _proposalRepository;
    private readonly IAgentSkillRepository _agentSkillRepository;
    private readonly IAgentRepository _agentRepository;
    private readonly ISkillLearningCaseRepository _caseRepository;
    private readonly ISkillLearningGoldenCaseRepository _goldenCaseRepository;
    private readonly IEvalRunRepository _evalRunRepository;
    private readonly IEvalRunItemRepository _evalRunItemRepository;
    private readonly ITurnGoldsetLoader _goldsetLoader;
    private readonly ILLMProviderFactory _providerFactory;
    private readonly ILLMRepository _llmRepository;
    private readonly ILogger<SkillDescriptionOptimizer> _logger;

    public SkillDescriptionOptimizer(
        ISkillSelectionTrajectoryRepository trajectoryRepository,
        IProposedSkillChangeRepository proposalRepository,
        IAgentSkillRepository agentSkillRepository,
        IAgentRepository agentRepository,
        ISkillLearningCaseRepository caseRepository,
        ISkillLearningGoldenCaseRepository goldenCaseRepository,
        IEvalRunRepository evalRunRepository,
        IEvalRunItemRepository evalRunItemRepository,
        ITurnGoldsetLoader goldsetLoader,
        ILLMProviderFactory providerFactory,
        ILLMRepository llmRepository,
        ILogger<SkillDescriptionOptimizer> logger)
    {
        _trajectoryRepository = trajectoryRepository;
        _proposalRepository = proposalRepository;
        _agentSkillRepository = agentSkillRepository;
        _agentRepository = agentRepository;
        _caseRepository = caseRepository;
        _goldenCaseRepository = goldenCaseRepository;
        _evalRunRepository = evalRunRepository;
        _evalRunItemRepository = evalRunItemRepository;
        _goldsetLoader = goldsetLoader;
        _providerFactory = providerFactory;
        _llmRepository = llmRepository;
        _logger = logger;
    }

    public async Task<int> GenerateProposalsAsync(
        int maxTrajectoriesToAnalyze, CancellationToken cancellationToken = default)
    {
        var agent = await _agentRepository.GetDefaultAgentAsync(cancellationToken);
        if (agent == null)
        {
            _logger.LogInformation("No default agent - Agent C skipped");
            return 0;
        }

        var corrections = await BuildCorrectionGroupsAsync(
            agent.Id, maxTrajectoriesToAnalyze, cancellationToken);
        var goldsetMisses = await BuildGoldsetGroupsAsync(cancellationToken);

        if (corrections.Count == 0 && goldsetMisses.Count == 0)
        {
            _logger.LogInformation("Neither a wrong-skill correction nor a goldset selection miss to analyze");
            return 0;
        }

        var (model, provider) = await GetCheapestModelAndProviderAsync();
        if (model == null || provider == null)
        {
            _logger.LogWarning("No enabled LLM model/provider available - Agent C skipped");
            return 0;
        }

        var generated = 0;

        foreach (var group in corrections)
        {
            cancellationToken.ThrowIfCancellationRequested();
            generated += await TryProposeFromCorrectionAsync(agent.Id, group, model, provider, cancellationToken);
        }

        foreach (var group in goldsetMisses)
        {
            cancellationToken.ThrowIfCancellationRequested();
            generated += await TryProposeFromGoldsetAsync(agent.Id, group, model, provider, cancellationToken);
        }

        _logger.LogInformation(
            "Agent C generated {Count} pending proposals from {Corrections} correction group(s) and "
                + "{Goldset} goldset selection-miss group(s)",
            generated, corrections.Count, goldsetMisses.Count);

        return generated;
    }

    private async Task<IReadOnlyList<CorrectionGroup>> BuildCorrectionGroupsAsync(
        Guid agentId, int maxTrajectoriesToAnalyze, CancellationToken cancellationToken)
    {
        var trajectories = await _trajectoryRepository.GetUncorrectedWrongSkillAsync(
            agentId, maxTrajectoriesToAnalyze, cancellationToken);

        return trajectories
            .Where(t => !string.IsNullOrWhiteSpace(t.LlmChosenSkill))
            .GroupBy(t => t.LlmChosenSkill!, StringComparer.OrdinalIgnoreCase)
            .Select(group => new CorrectionGroup(group.Key, [.. group.Take(MaxEvidencePerProposal)]))
            .ToList();
    }

    private async Task<IReadOnlyList<GoldsetMissGroup>> BuildGoldsetGroupsAsync(
        CancellationToken cancellationToken)
    {
        var run = await _evalRunRepository.GetLatestFullRunAsync(
            TurnEvalDefaults.DefaultGoldset, TurnEvalScorer.ScorerVersion, cancellationToken);

        if (run == null)
        {
            return [];
        }

        IReadOnlyList<TurnGoldsetItem> goldsetItems;
        try
        {
            goldsetItems = await _goldsetLoader.LoadAsync(
                TurnEvalDefaults.DefaultGoldset, cancellationToken);
        }
        catch (Exception exception) when (exception is not OperationCanceledException)
        {
            _logger.LogWarning(
                exception, "Goldset could not be read; the eval source of Agent C is skipped this run");
            return [];
        }

        var trainItems = goldsetItems
            .Where(item => GoldsetPartitioner.IsTrain(item.Id))
            .GroupBy(item => item.Id, StringComparer.Ordinal)
            .ToDictionary(group => group.Key, group => group.First(), StringComparer.Ordinal);

        if (trainItems.Count == 0)
        {
            return [];
        }

        var misses = await _evalRunItemRepository.ListUnconsumedSelectionMissesAsync(
            run.Id,
            [.. trainItems.Keys],
            SkillLearningDefaults.MaxGoldsetMissesPerRun,
            cancellationToken);

        if (misses.Count == 0)
        {
            return [];
        }

        return misses
            .Where(miss => !string.IsNullOrWhiteSpace(miss.ChosenTool))
            .Where(miss => GoldsetPartitioner.IsTrain(miss.ItemId))
            .Where(miss => trainItems.ContainsKey(miss.ItemId))
            .GroupBy(miss => miss.ChosenTool!, StringComparer.OrdinalIgnoreCase)
            .OrderByDescending(group => group.Count())
            .ThenBy(group => group.Key, StringComparer.OrdinalIgnoreCase)
            .Take(SkillLearningDefaults.MaxGoldsetProposalsPerRun)
            .Select(group =>
            {
                var evidence = group.Take(MaxEvidencePerProposal).ToList();
                return new GoldsetMissGroup(
                    group.Key,
                    evidence,
                    [.. evidence.Select(miss => trainItems[miss.ItemId].Message)]);
            })
            .ToList();
    }

    private async Task<int> TryProposeFromCorrectionAsync(
        Guid agentId,
        CorrectionGroup group,
        LLMModel model,
        ILLMProvider provider,
        CancellationToken cancellationToken)
    {
        var skill = await ResolveOpenSkillAsync(agentId, group.WronglyChosenSkill, cancellationToken);
        if (skill == null)
        {
            return 0;
        }

        var examples = group.Evidence.Select(t => t.IntentExcerpt).ToList();
        var suggestion = await GenerateSuggestionAsync(skill, examples, model, provider, cancellationToken);
        if (suggestion == null)
        {
            return 0;
        }

        await FreezeIntendedTargetsAsync(group.Evidence, skill.Name, cancellationToken);
        await AddProposalAsync(skill, suggestion, examples, ProposedChangeOrigins.Correction, cancellationToken);

        await _trajectoryRepository.MarkSharpenedAsync(
            [.. group.Evidence.Select(t => t.Id)], DateTime.UtcNow, cancellationToken);

        return 1;
    }

    private async Task<int> TryProposeFromGoldsetAsync(
        Guid agentId,
        GoldsetMissGroup group,
        LLMModel model,
        ILLMProvider provider,
        CancellationToken cancellationToken)
    {
        var skill = await ResolveOpenSkillAsync(agentId, group.WronglyChosenSkill, cancellationToken);
        if (skill == null)
        {
            return 0;
        }

        var suggestion = await GenerateSuggestionAsync(
            skill, group.Examples, model, provider, cancellationToken);
        if (suggestion == null)
        {
            return 0;
        }

        await AddProposalAsync(
            skill, suggestion, group.Examples, ProposedChangeOrigins.GoldsetEval, cancellationToken);

        await _evalRunItemRepository.MarkConsumedAsync(
            [.. group.Evidence.Select(item => item.Id)], DateTime.UtcNow, cancellationToken);

        return 1;
    }

    private async Task<AgentSkill?> ResolveOpenSkillAsync(
        Guid agentId, string skillName, CancellationToken cancellationToken)
    {
        var skill = await _agentSkillRepository.GetByNameAsync(agentId, skillName, cancellationToken);
        if (skill == null)
        {
            return null;
        }

        if (await _proposalRepository.HasOpenProposalForSkillAsync(
                skill.Id, ProposedChangeFields.Description, cancellationToken))
        {
            _logger.LogDebug("Skill {Name} already has an open proposal - skip", skill.Name);
            return null;
        }

        return skill;
    }

    private async Task AddProposalAsync(
        AgentSkill skill,
        Suggestion suggestion,
        IReadOnlyList<string> examples,
        string origin,
        CancellationToken cancellationToken)
    {
        await _proposalRepository.AddAsync(
            new ProposedSkillChange
            {
                Id = Guid.NewGuid(),
                AgentId = skill.AgentId,
                SkillId = skill.Id,
                SkillName = skill.Name,
                Field = ProposedChangeFields.Description,
                Origin = origin,
                ValueBefore = skill.Description,
                ValueAfter = suggestion.Description,
                Justification = suggestion.Justification,
                Status = ProposedChangeStatuses.Pending,
                EvidenceJson = JsonSerializer.Serialize(examples),
                CreateTime = DateTime.UtcNow
            },
            cancellationToken);
    }

    // Only a correction that named where the wish belonged can be frozen. An implicit correction names
    // nothing, and a correction pointing back at the skill being narrowed contradicts itself - freezing
    // either would hand the gate an expectation the sharpening is designed to break.
    private async Task FreezeIntendedTargetsAsync(
        IReadOnlyList<SkillSelectionTrajectory> evidence,
        string wronglyChosenSkill,
        CancellationToken cancellationToken)
    {
        foreach (var trajectory in evidence)
        {
            cancellationToken.ThrowIfCancellationRequested();

            if (string.IsNullOrWhiteSpace(trajectory.IntentExcerpt))
            {
                continue;
            }

            var expected = await _caseRepository.FindExpectedSkillByTrajectoryAsync(
                trajectory.Id, cancellationToken);

            if (string.IsNullOrWhiteSpace(expected)
                || string.Equals(expected, wronglyChosenSkill, StringComparison.OrdinalIgnoreCase))
            {
                continue;
            }

            if (await _goldenCaseRepository.ExistsAsync(trajectory.IntentExcerpt, expected, cancellationToken))
            {
                continue;
            }

            await _goldenCaseRepository.AddAsync(
                new SkillLearningGoldenCase
                {
                    Id = Guid.NewGuid(),
                    Query = trajectory.IntentExcerpt,
                    Locale = trajectory.Locale,
                    ExpectedSourceId = expected,
                    Origin = GoldenCaseOrigins.Cluster,
                    Partition = GoldenCasePartitions.Holdout
                },
                cancellationToken);
        }
    }

    private async Task<Suggestion?> GenerateSuggestionAsync(
        AgentSkill skill,
        IReadOnlyList<string> examples,
        LLMModel model,
        ILLMProvider provider,
        CancellationToken cancellationToken)
    {
        var examplesBlock = string.Join("\n", examples.Select(e => $"- {e}"));
        var userMessage =
            $"Skill name: {skill.Name}\n" +
            $"Current description: {skill.Description}\n" +
            $"Examples of user queries that this skill was WRONGLY chosen for:\n{examplesBlock}\n\n" +
            "Suggest a tighter description.";

        var request = new LLMProviderRequest
        {
            Message = userMessage,
            SystemPrompt = SystemPrompt,
            ModelId = model.ApiModelId,
            ConversationHistory = [],
            AvailableFunctions = [],
            Temperature = OptimizerTemperature,
            MaxTokens = OptimizerMaxTokens,
            SupportedParameters = model.SupportedParameters,
            CostPerInputToken = model.CostPerInputToken,
            CostPerOutputToken = model.CostPerOutputToken
        };

        try
        {
            var response = await provider.ProcessAsync(request);
            if (!response.Success || string.IsNullOrWhiteSpace(response.Content))
            {
                _logger.LogDebug("Optimizer LLM call returned no content for skill {Name}", skill.Name);
                return null;
            }

            return ParseSuggestion(response.Content, skill.Description);
        }
        catch (Exception ex) when (ex is not OperationCanceledException)
        {
            _logger.LogWarning(ex, "Optimizer LLM call failed for skill {Name}", skill.Name);
            return null;
        }
    }

    private Suggestion? ParseSuggestion(string content, string currentDescription)
    {
        try
        {
            var trimmed = ExtractJsonObject(content);
            if (string.IsNullOrWhiteSpace(trimmed)) return null;

            using var doc = JsonDocument.Parse(trimmed);
            var description = doc.RootElement.TryGetProperty("description", out var d) ? d.GetString() : null;
            var justification = doc.RootElement.TryGetProperty("justification", out var j) ? j.GetString() : string.Empty;

            if (string.IsNullOrWhiteSpace(description)) return null;
            description = description.Trim();
            if (description.Length < MinDescriptionLength || description.Length > MaxDescriptionLength) return null;
            if (string.Equals(description, currentDescription.Trim(), StringComparison.OrdinalIgnoreCase)) return null;

            return new Suggestion(description, (justification ?? string.Empty).Trim());
        }
        catch (JsonException ex)
        {
            _logger.LogDebug(ex, "Optimizer suggestion JSON parse failed");
            return null;
        }
    }

    private static string? ExtractJsonObject(string content)
    {
        var start = content.IndexOf('{');
        var end = content.LastIndexOf('}');
        if (start < 0 || end <= start) return null;
        return content.Substring(start, end - start + 1);
    }

    private async Task<(LLMModel? model, ILLMProvider? provider)> GetCheapestModelAndProviderAsync()
    {
        var models = await _llmRepository.GetModelsAsync(onlyEnabled: true);
        var cheapest = models.OrderBy(m => m.CostPerInputToken + m.CostPerOutputToken).FirstOrDefault();
        if (cheapest == null) return (null, null);
        var provider = await _providerFactory.GetProviderForModelAsync(cheapest.ModelId);
        return (cheapest, provider);
    }

    private sealed record Suggestion(string Description, string Justification);

    private sealed record CorrectionGroup(
        string WronglyChosenSkill, IReadOnlyList<SkillSelectionTrajectory> Evidence);

    private sealed record GoldsetMissGroup(
        string WronglyChosenSkill, IReadOnlyList<EvalRunItem> Evidence, IReadOnlyList<string> Examples);
}
